## 1. First, let's update the CategoryViewModel to include the "All" category

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/category/CategoryViewModel.kt
class CategoryViewModel @Inject constructor(
 private val categoryRepository: CategoryRepository
) : ViewModel() {

 private val _categoriesState = MutableStateFlow<CategoriesState>(CategoriesState.Loading)
 val categoriesState: StateFlow<CategoriesState> = _categoriesState

 init {
 loadCategories()
 }

 private fun loadCategories() {
 viewModelScope.launch {
 categoryRepository.getAllCategories()
 .catch { e ->
 _categoriesState.value = CategoriesState.Error(e.message ?: "Unknown error")
 }
 .collect { categories ->
 // Add "All" category at the beginning of the list
 val allCategory = Category(id = "all", name = "All")
 val categoriesWithAll = listOf(allCategory) + categories
 _categoriesState.value = CategoriesState.Success(categoriesWithAll)
 }
 }
 }

 // Rest of the class remains the same...
}
```

## 2. Now, let's create the horizontal component for categories

```kotlin:app/src/main/java/tungp/android/bazarbooks/components/CategoryChips.kt
package tungp.android.bazarbooks.components

import androidx.compose.foundation.horizontalScroll
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import tungp.android.bazarbooks.data.model.Category

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CategoryChips(
 categories: List<Category>,
 onCategorySelected: (Category) -> Unit,
 modifier: Modifier = Modifier,
 selectedCategoryId: String = "all"
) {
 Row(
 modifier = modifier
 .fillMaxWidth()
 .horizontalScroll(rememberScrollState())
 .padding(horizontal = 16.dp, vertical = 8.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 categories.forEach { category ->
 val isSelected = category.id == selectedCategoryId
 FilterChip(
 selected = isSelected,
 onClick = { onCategorySelected(category) },
 label = { Text(category.name) },
 colors = FilterChipDefaults.filterChipColors(
 selectedContainerColor = MaterialTheme.colorScheme.primaryContainer,
 selectedLabelColor = MaterialTheme.colorScheme.onPrimaryContainer
 )
 )
 }
 }
}
```

