 CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
 }
 }
 is CategoryViewModel.CategoriesState.Error -> {
 val errorState = categoriesState as CategoryViewModel.CategoriesState.Error
 Box(modifier = Modifier.fillMaxSize()) {
 Column(
 modifier = Modifier.align(Alignment.Center),
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text("Error: ${errorState.message}")
 Button(onClick = { /* Retry logic here */ }) {
 Text("Retry")
 }
 }
 }
 }
 is CategoryViewModel.CategoriesState.Success -> {
 val categories = (categoriesState as CategoryViewModel.CategoriesState.Success).categories

 // Horizontal category chips
 CategoryChips(
 categories = categories,
 onCategorySelected = { category ->
 setSelectedCategoryId(category.id)
 // If "All" is selected, we'll show all books
 // Otherwise navigate to the specific category
 if (category.id != "all") {
 navController.navigate("${CategoryRouteScreen.CategoryDetail.route}/${category.id}")
 }
 },
 selectedCategoryId = selectedCategoryId
 )

 // Display category content based on selection
 if (selectedCategoryId == "all") {
 // Show all books
 AllBooksContent()
 } else {
 // Show the specific category's books
 val selectedCategory = categories.find { it.id == selectedCategoryId }
 selectedCategory?.let {
 CategoryDetailContent(category = it)
 }
 }
 }
 }
 }
}

