## 6. Update the BookRepository to get all books and books by category

```kotlin:app/src/main/java/tungp/android/bazarbooks/data/repository/BookRepository.kt
package tungp.android.bazarbooks.data.repository

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOn
import retrofit2.http.GET
import retrofit2.http.Path
import tungp.android.bazarbooks.data.model.Book
import javax.inject.Inject

interface BookApiService {
 @GET("books")
 suspend fun getAllBooks(): List<Book>

 @GET("categories/{categoryId}/books")
 suspend fun getBooksByCategory(@Path("categoryId") categoryId: String): List<Book>
}

class BookRepository @Inject constructor(
 private val bookApiService: BookApiService
) {
 fun getAllBooks(): Flow<List<Book>> = flow {
 try {
 val books = bookApiService.getAllBooks()
 emit(books)
 } catch (e: Exception) {
 emit(emptyList())
 }
 }.flowOn(Dispatchers.IO)

 fun getBooksByCategory(categoryId: String): Flow<List<Book>> = flow {
 try {
 val books = bookApiService.getBooksByCategory(categoryId)
 emit(books)
 } catch (e: Exception) {
 emit(emptyList())
 }
 }.flowOn(Dispatchers.IO)
}
```

