## 8. Create a BookViewModel for handling book data

```kotlin:app/src/main/java/tungp/android/bazarbooks/screens/book/BookViewModel.kt
package tungp.android.bazarbooks.screens.book

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.launch
import tungp.android.bazarbooks.data.model.Book
import tungp.android.bazarbooks.data.repository.BookRepository
import javax.inject.Inject

@HiltViewModel
class BookViewModel @Inject constructor(
 private val bookRepository: BookRepository
) : ViewModel() {

 private val _booksState = MutableStateFlow<BooksState>(BooksState.Loading)
 val booksState: StateFlow<BooksState> = _booksState

 init {
 loadAllBooks()
 }

 fun loadAllBooks() {
 viewModelScope.launch {
 _booksState.value = BooksState.Loading
 bookRepository.getAllBooks()
 .catch { e ->
 _booksState.value = BooksState.Error(e.message ?: "Failed to load books")
 }
 .collect { books ->
 _booksState.value = BooksState.Success(books)
 }
 }
 }

 fun loadBooksByCategory(categoryId: String) {
 if (categoryId == "all") {
 loadAllBooks()
 return
 }

 viewModelScope.launch {
 _booksState.value = BooksState.Loading
 bookRepository.getBooksByCategory(categoryId)
 .catch { e ->
 _booksState.value = BooksState.Error(e.message ?: "Failed to load books")
 }
 .collect { books ->
 _booksState.value = BooksState.Success(books)
 }
 }
 }

 sealed class BooksState {
 object Loading : BooksState()
 data class Success(val books: List<Book>) : BooksState()
 data class Error(val message: String) : BooksState()
 }
}
```

