// Make sure your navigation route definitions correctly handle parameters
sealed class CategoryRouteScreen(val route: String) {
 object CategoryList : CategoryRouteScreen("category_list")
 object CategoryDetail : CategoryRouteScreen("category_detail")
}

// In your NavHost setup
NavHost(navController = navController, startDestination = CategoryRouteScreen.CategoryList.route) {
 composable(CategoryRouteScreen.CategoryList.route) {
 CategoryScreen(navController = navController)
 }

 composable(
 route = "${CategoryRouteScreen.CategoryDetail.route}/{bookId}",
 arguments = listOf(navArgument("bookId") { type = NavType.StringType })
 ) { backStackEntry ->
